import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class P1047D {
    private static final Map<Long, Long> SPECIAL = new HashMap<>();

    static {
        SPECIAL.put(key(2L, 2L), 0L);
        SPECIAL.put(key(2L, 3L), 4L);
        SPECIAL.put(key(2L, 7L), 12L);
        SPECIAL.put(key(3L, 3L), 8L);
    }

    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        long n = scan.nextInt();
        long m = scan.nextInt();
        long min = Math.min(n, m);
        long max = Math.max(n, m);

        Long special = SPECIAL.get(key(min, max));
        long ans;

        if (special != null) {
            ans = special;
        } else if (min == 1) {
            ans = max / 6 * 6 + 2 * Math.max(0, max % 6 - 3);
        } else {
            ans = min * max;
            if (max % 2 != 0) {
                ans -= ans % 2;
            }
        }

        System.out.println(ans);
    }

    private static long key(long a, long b) {
        return (a << 32) + b;
    }
}
